commands.command:
set -eu
snapshot=/srv/snapshots/manual.0/data/srv/data
manifest() {
  find "$1" -mindepth 1 -print | sort | while IFS= read -r p; do
    rel=${p#"$1"/}
    meta=$(stat -c '%a|%u|%g' "$p")
    if [ -L "$p" ]; then printf 'L|%s|%s|%s\n' "$rel" "$meta" "$(readlink "$p")";
    elif [ -d "$p" ]; then printf 'D|%s|%s\n' "$rel" "$meta";
    elif [ -f "$p" ]; then printf 'F|%s|%s|%s|%s\n' "$rel" "$meta" "$(stat -c '%s' "$p")" "$(sha256sum "$p" | cut -d' ' -f1)";
    fi
  done
}
manifest "$snapshot" > /root/snapshot-captured.manifest
cmp -s /root/snapshot-baseline.manifest /root/snapshot-captured.manifest
printf 'SNAPSHOT_CAPTURE_MATCH=yes\n'
printf 'SNAPSHOT_PATH=%s\n' "$snapshot"
printf 'SNAPSHOT_MANIFEST_SHA256='
sha256sum /root/snapshot-captured.manifest | cut -d' ' -f1
cat /root/snapshot-captured.manifest
